package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.RequireEmailVerificationVO;

class RequireEmailVerificationValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of require email verification of tenant config")
  void test_require_email_verification_value_holder_assign_plain_value() {
    Object holder = new Object();
    RequireEmailVerificationValueHolder<Object> value =
        new RequireEmailVerificationValueHolder<>(holder);
    Assertions.assertSame(holder, value.requireEmailVerification(true),
        "Setters must return the holder");
    Assertions.assertTrue(value.getRequireEmailVerificationValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getRequireEmailVerification().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of require email verification of tenant config")
  void test_require_email_verification_value_holder_assign_value_object() {
    Object holder = new Object();
    RequireEmailVerificationValueHolder<Object> value =
        new RequireEmailVerificationValueHolder<>(holder);
    RequireEmailVerificationVO vo = RequireEmailVerificationVO.from(true);
    Assertions.assertFalse(value.getRequireEmailVerificationValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.requireEmailVerification(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getRequireEmailVerificationValue().orElseThrow());
    Assertions.assertSame(holder, value.requireEmailVerification(Optional.empty()));
    Assertions.assertFalse(value.getRequireEmailVerificationValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.requireEmailVerification(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRequireEmailVerificationValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of require email verification of tenant config against the original")
  void test_require_email_verification_value_holder_read() {
    Object holder = new Object();
    RequireEmailVerificationValueHolder<Object> value =
        new RequireEmailVerificationValueHolder<>(holder);
    RequireEmailVerificationVO vo = RequireEmailVerificationVO.from(true);
    RequireEmailVerificationVO other = RequireEmailVerificationVO.from(true);
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getRequireEmailVerificationValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRequireEmailVerification(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readRequireEmailVerification(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.requireEmailVerification(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRequireEmailVerification(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRequireEmailVerification(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of require email verification of tenant config")
  void test_require_email_verification_value_holder_unset() {
    Object holder = new Object();
    RequireEmailVerificationValueHolder<Object> value =
        new RequireEmailVerificationValueHolder<>(holder);
    RequireEmailVerificationVO vo = RequireEmailVerificationVO.from(true);
    value.requireEmailVerification(vo);
    Assertions.assertSame(holder,
        value.unsetRequireEmailVerificationIfMatches("requireEmailVerification_other"));
    Assertions.assertTrue(value.getRequireEmailVerificationValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetRequireEmailVerificationIfMatches("requireEmailVerification"));
    Assertions.assertFalse(value.getRequireEmailVerificationValue().isPresent(),
        "The field name must clear the value");
    value.requireEmailVerification(vo);
    Assertions.assertSame(holder, value.unsetRequireEmailVerification());
    Assertions.assertFalse(value.getRequireEmailVerificationValue().isPresent(),
        "Unset must clear the value");
  }
}
